 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Hi! Thanks for contacting Nimbus Telecom. I'm Meera. How can I help you today? 😊",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "I'm so annoyed. My bill is way higher than it should be this month. This is ridiculous!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'm sorry to hear that you're frustrated with your bill. I'll do my best to get this sorted for you. Can I start by getting your account number and date of birth please?",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "Fine. Account number is 11894083 and my DOB is 01/01/1968.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Rohan Iyer. I'm looking at your account now. I see a charge for a premium data package that you didn't request. My apologies for the error.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Exactly! I never signed up for that. If this keeps happening, I'm just going to cancel my service and switch to another provider.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I completely understand. I will raise a refund request for the wrong charge right now to get this corrected.",
      "tags": [
        "action:refund_request"
      ]
    },
    {
      "speaker": "agent",
      "text": "Just so you know, the credit is subject to approval and usually takes 7-10 business days to appear on your statement.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "Okay, that works. I also need to pay the remaining balance now so it doesn't get cut off. Can I do that here?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Yes, you can. Please provide the card details you'd like to use.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It's four two four six four zero zero eight five nine nine seven nine eight seven two",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My address is 78 Brigade Road and my phone is 92446 85314.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Payment processed successfully! Is there anything else I can help you with today? I've requested the refund for the overcharge, which you'll see in 7-10 business days. Goodbye!",
      "tags": [
        "closure"
      ]
    },
    {
      "speaker": "customer",
      "text": "No, that's all. Thanks for fixing it so quickly, Meera! 😊",
      "tags": []
    }
  ]
}
